def is_balanced(s: str) -> bool:
    """
    Return True if every bracket in the string `s` is closed in the correct order.
    Brackets are the pairs: '()', '[]', '{}'. Non‑bracket characters are ignored.
    """
    # Maps closing bracket to its corresponding opening bracket
    matching = {')': '(', ']': '[', '}': '{'}
    opening_brackets = set(matching.values())
    stack = []

    for ch in s:
        if ch in opening_brackets:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
        # else: ignore any other characters

    return not stack
