def int_to_roman(n: int) -> str:
    """Convert an integer (1‑3999) to its Roman numeral representation."""
    if not isinstance(n, int):
        raise ValueError("n must be an integer")
    if n < 1 or n > 3999:
        raise ValueError("n must be between 1 and 3999 inclusive")

    # List of value‑symbol pairs in descending order, including subtractive forms
    value_symbol = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    roman = []
    for val, sym in value_symbol:
        while n >= val:
            roman.append(sym)
            n -= val
    return ''.join(roman)
