def compare_semver(a: str, b: str) -> int:
    """
    Compare two Semantic Versioning 2.0.0 strings.
    Returns -1 if a < b, 0 if a == b, 1 if a > b.
    """
    def parse(version: str):
        version = version.strip()
        # Strip optional leading 'v' or 'V'.
        if version.startswith('v') or version.startswith('V'):
            version = version[1:]

        # Discard build metadata (anything after '+').
        if '+' in version:
            version = version.split('+', 1)[0]

        # Separate core version from pre‑release identifiers.
        if '-' in version:
            core, pre = version.split('-', 1)
        else:
            core, pre = version, None

        core_parts = tuple(int(x) for x in core.split('.'))

        # Pre‑release is None if absent, otherwise a list of identifiers.
        pre_parts = pre.split('.') if pre else None
        return core_parts, pre_parts

    # Parse both version strings.
    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)

    # Compare the core (major.minor.patch) numerically.
    if core_a < core_b:
        return -1
    if core_a > core_b:
        return 1

    # Core parts are equal – evaluate pre‑release.
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        # A normal version has higher precedence than a pre‑release.
        return 1
    if pre_b is None:
        return -1

    # Helper to create a comparable key for each pre‑release identifier.
    def identifier_key(ident: str):
        # Numeric‑only identifiers compare as integers and are lower than alphanumeric.
        if ident.isdigit():
            return (0, int(ident))
        else:
            return (1, ident)

    keys_a = [identifier_key(x) for x in pre_a]
    keys_b = [identifier_key(x) for x in pre_b]

    if keys_a < keys_b:
        return -1
    if keys_a > keys_b:
        return 1
    return 0
