from collections import OrderedDict

class LRUCache:
    """Least Recently Used (LRU) cache with O(1) average get/put."""
    __slots__ = ('capacity', 'cache')

    def __init__(self, capacity: int):
        if capacity < 0:
            raise ValueError("capacity must be non‑negative")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key: int) -> int:
        """Return the value for key if present, otherwise -1.
        The accessed key becomes the most recently used."""
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)      # mark as most recent
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        """Insert or update key. If size exceeds capacity,
        evict the least recently used key."""
        if self.capacity == 0:
            return                      # nothing can be stored

        if key in self.cache:
            self.cache.move_to_end(key) # refresh recency
            self.cache[key] = value
        else:
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)  # evict LRU
            self.cache[key] = value
